OBSERVED:
create or replace view V(
	ID,
	MARKER
) as select id, marker from t;

create or replace semantic view SV
	tables (
		SILVER.S1_OTHER.T primary key (ID)
	)
	dimensions (
		T.MARKER_DIM as marker
	)
	metrics (
		T.ROW_COUNT as count(*)
	);

create or replace semantic view SV_PUB
	tables (
		SILVER.S1_PUB.T primary key (ID)
	)
	dimensions (
		T.MARKER_DIM as marker
	)
	metrics (
		T.ROW_COUNT as count(*)
	);
